BEGIN;
INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('g-kentei-c', 'G検定（JDLA ジェネラリスト検定） Set C',
        'JDLA G検定 対策 第3弾。シラバス2024（2024年11月試験より適用）準拠。Set A・B が扱っていないテーマを中心に構成。個人情報保護法は範囲外（保有資格のため意図的に除外）。本試験の再現ではなく学習用オリジナル。',
        '#0B5CAB', 52)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('1. 人工知能とは', '#58a6ff', 0),
  ('2. 人工知能をめぐる動向', '#79c0ff', 1),
  ('3. 機械学習の概要', '#3fb950', 2),
  ('4. ディープラーニングの概要', '#a371f7', 3),
  ('5. ディープラーニングの要素技術', '#d2a8ff', 4),
  ('6. ディープラーニングの応用例', '#f0883e', 5),
  ('7. AIの社会実装に向けて', '#e3b341', 6),
  ('8. AIに必要な数理・統計知識', '#39c5cf', 7),
  ('9. AIに関する法律と契約', '#f85149', 8),
  ('10. AI倫理・AIガバナンス', '#ff7b72', 9)
) AS v(name, color, sort_order)
WHERE s.slug = 'g-kentei-c'
ON CONFLICT (subject_id, name) DO NOTHING;
COMMIT;
BEGIN;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q1', '哲学者サールの区分で、AIは単なる道具ではなく、人間と同じように本物の意識や理解を持ちうるとする立場はどれか。', NULL, '["強いAI", "弱いAI", "特化型AI", "記号処理AI"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIが本物の意識や理解を持ちうるとする立場は？", "point": "「AIも本物の心・理解を持てる」とする立場なら、強いAI。", "kid": "弱いAIが「賢いフリの道具でいい」なのに対し、強いAIは「AIも人間と同じように本当に意識や理解を持てる」と考える立場。", "eg": "ロボットが「演じている」のか「本当に感じている」のか。本当に感じていると考えるのが強いAI。", "terms": [["強いAI", "AIも人間と同じ本物の意識や理解を持ちうるとする立場"], ["弱いAI", "意識は無くても、賢く振る舞う道具として役立てばよいとする立場"]], "think": "「本物の心・理解を持てる」とするなら強いAI。「道具として振る舞えれば十分」なら弱いAI。心の有無で分ける。", "vs": "弱いAIは道具として役立てばよいとする立場、特化型AIは特定の作業だけこなすAIの分類、記号処理AIは記号操作で動く古典的AIで、いずれも「本物の意識を持てるか」の立場ではない。", "usecase": "AGI(汎用人工知能)や意識をめぐる議論の出発点。AIに何をどこまで期待・懸念すべきかを整理する軸になる。", "opt": ["正解。AIも本物の意識や理解を持ちうるとするのが強いAI。", "意識は無くても道具として役立てばよいとする立場で、強いAIの逆。", "特定の作業だけこなすAIの分類で、意識の有無の立場ではない。", "記号操作で動く古典的なAIの説明で、意識を持てるかの立場ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q2', 'AIの能力段階のうち、人間が特徴を設計しなくても、データから「注目すべき特徴」そのものを自ら見つけ出して学習する最も進んだ段階はどれか。', NULL, '["特徴量そのものをデータから自ら学習する段階", "人間が設計した特徴量を使って対応を学習する段階", "入力に応じた振る舞いを人間が全て定義する段階", "決められた振る舞いしかしない単純な制御の段階"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "特徴そのものを自ら見つけて学習する、最も進んだAIの段階は？", "point": "「注目すべき特徴まで自分で見つけて学ぶ」なら、特徴表現学習（ディープラーニング相当・最上位）。", "kid": "昔のAIは「どこに注目するか(特徴)」を人間が指定していた。ディープラーニングは、その注目点まで自分でデータから見つける。人の手を最も離れた段階。", "eg": "猫を見分けるのに「ヒゲに注目して」と人が教えるのが従来。「何に注目すれば猫と分かるか」まで自分で気づくのがこの段階。", "terms": [["特徴表現学習", "データから特徴量そのものを自ら学習する段階。ディープラーニングが該当し、AIレベル分類の最上位"], ["特徴量", "予測の手がかりになる項目。従来は人が設計していた"]], "think": "「特徴量まで自分で学ぶ」なら特徴表現学習(最上位)。人が特徴を設計する段階や、決められた動きだけの制御より進んでいる。", "vs": "人が設計した特徴で学ぶ段階、振る舞いを人が全部定義する段階、決められた動きだけの制御は、いずれも特徴を自分で見つける最上位より前の段階。", "usecase": "「なぜディープラーニングが強いか」の核心。特徴設計の職人技が要らなくなり、画像・音声など生データから直接学べるようになった。", "opt": ["正解。特徴量そのものを自ら学習する最も進んだ段階。", "人が設計した特徴を使う段階で、特徴自体は自分で見つけていない。", "振る舞いを人が全部定義する段階で、学習していない。", "決められた動きだけの単純な制御で、最も単純な段階。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q3', '知能は頭の中の記号処理だけでは成り立たず、身体を通じて環境と関わる経験があってこそ育つ、という考え方を指す語はどれか。', NULL, '["身体性", "記号接地", "フレーム問題", "チューリングテスト"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "知能には身体を通じた環境との関わりが必要、とする考え方は？", "point": "「知能は身体を通じた経験があって育つ」とする考えなら、身体性。", "kid": "「甘い」「重い」を本当に理解するには、実際に舐めたり持ち上げたりする身体の経験が要る、という考え方。頭の中の記号処理だけでは足りないとする立場。", "eg": "泳ぎ方を本で読むだけでは泳げず、水に入って体で覚える必要がある、あの感覚。", "terms": [["身体性", "知能は身体を通じて環境と関わる経験があってこそ育つ、という考え方"], ["記号接地（シンボルグラウンディング）", "記号を実世界の意味に結びつけられない問題。身体性はその解決の鍵とされる"]], "think": "「身体を通じた経験が知能に要る」なら身体性。記号だけでは意味に届かないという記号接地問題と深く関わる。", "vs": "記号接地は記号と意味が結びつかない問題そのもの、フレーム問題は考える範囲を絞れない難問、チューリングテストは知能の判定方法で、いずれも身体性の考え方そのものではない。", "usecase": "ロボットやAIが実世界を本当に理解するには、センサーや身体を通じた相互作用が要る、という研究の方向づけになる。", "opt": ["正解。身体を通じた経験があって知能が育つとする考え方。", "記号と意味が結びつかない問題で、身体性という考え方そのものではない。", "考える範囲を絞れない難問で、身体性ではない。", "知能の判定方法で、身体性の考え方ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q4', '「高度な論理的思考はAIに実装しやすいのに、歩く・物をつかむといった幼児でもできる感覚運動の能力ほど実装が難しい」という逆説を指す語はどれか。', NULL, '["モラベックのパラドックス", "フレーム問題", "シンボルグラウンディング問題", "組合せ爆発"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "高度な論理はAIに簡単なのに、歩く・つかむは難しい、という逆説は？", "point": "「難しい論理は簡単、簡単な運動は難しい」という逆説なら、モラベックのパラドックス。", "kid": "チェスや計算のような「頭のいい人ほど難しい」ことはAIには意外と簡単。逆に、歩く・物をつかむような幼児でもできることほどAIには難しい。この直感と逆の現象。", "eg": "電卓は難しい計算を一瞬でこなすのに、コップを転ばさず持ち上げるロボットを作る方がずっと大変、というちぐはぐさ。", "terms": [["モラベックのパラドックス", "高度な推論はAIに実装しやすく、感覚運動の能力ほど実装が難しいという逆説"], ["身体性", "感覚運動が知能に不可欠だとする考え。この逆説と関わる"]], "think": "「論理は簡単・感覚運動は難しい」という直感と逆の話ならモラベックのパラドックス。考える範囲を絞れないフレーム問題とは別。", "vs": "フレーム問題は考える範囲を絞れない難問、シンボルグラウンディング問題は記号と意味が結びつかない問題、組合せ爆発は場合の数が急増する現象で、いずれもこの逆説ではない。", "usecase": "ロボット開発の難しさの本質を言い当てる言葉。事務作業の自動化は進んでも、身体を使う作業の自動化が遅れる理由の説明になる。", "opt": ["正解。高度な推論は簡単で、感覚運動ほど難しいという逆説。", "考える範囲を絞れない難問で、この逆説ではない。", "記号と意味が結びつかない問題で、感覚運動の逆説ではない。", "場合の数が急増する現象で、この逆説とは別。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q5', '1970年代に作られ、患者の症状から感染症を診断し、抗生物質を提案した代表的なエキスパートシステムはどれか。', NULL, '["MYCIN", "ELIZA", "AlphaGo", "word2vec"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "感染症の診断を支援した代表的なエキスパートシステムは？", "point": "「感染症の診断を助けた第2次ブームのエキスパートシステム」なら、MYCIN。", "kid": "「熱があって、この菌が疑われるなら、この抗生物質」といった医師のルールを大量に詰め込み、感染症の診断を助けた初期の専門家システム。", "eg": "ベテラン医師の判断マニュアルを一冊のプログラムにして、診断を手伝わせたようなもの。", "terms": [["MYCIN", "患者の症状から感染症を診断し治療を提案した、代表的なエキスパートシステム"], ["エキスパートシステム", "専門家の知識をルールとして詰め込み、判断をまねる仕組み"]], "think": "「感染症診断・ルールベース・第2次ブーム」ならMYCIN。おうむ返しの対話プログラムELIZAとは目的が違う。", "vs": "ELIZAはおうむ返しで対話を装った初期プログラム、AlphaGoは囲碁AI、word2vecは単語をベクトルにする手法で、いずれも感染症診断のエキスパートシステムではない。", "usecase": "専門家の知識をルール化する試みの代表例。判断根拠を説明できる強みと、知識をルール化する難しさ(知識獲得のボトルネック)の両方を示す。", "opt": ["正解。感染症の診断を支援した代表的なエキスパートシステム。", "おうむ返しで対話を装った初期プログラムで、診断システムではない。", "囲碁AIで、感染症診断のシステムではない。", "単語をベクトルにする手法で、エキスパートシステムではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q6', '探索で、必ず最適とは限らないが、経験則を使って「良さそうな方向」を優先し、効率よく答えに近づく手がかりを指す語はどれか。', NULL, '["ヒューリスティック", "ブルートフォース", "バックプロパゲーション", "アノテーション"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "経験則で「良さそうな方向」を優先し、探索を効率化する手がかりは？", "point": "「経験則で良さそうな方を優先して探索を効率化する目安」なら、ヒューリスティック。", "kid": "すべてをしらみつぶしに調べるのではなく、「たぶんこっちが近い」という経験則の目安を使って、当たりをつけて効率よく探す考え方。", "eg": "知らない町で駅を探すとき、人通りの多い方へ行けば近い、という当たりのつけ方。", "terms": [["ヒューリスティック", "必ず最適とは限らないが、経験則で良さそうな方向を優先して効率よく探す目安"], ["ブルートフォース（総当たり）", "可能性を全部調べる方法。確実だが時間がかかる"]], "think": "「経験則で当たりをつけて効率化」ならヒューリスティック。全部調べる総当たり(ブルートフォース)とは逆の発想。", "vs": "ブルートフォースは全部調べる総当たり、バックプロパゲーションはニューラルネットの学習手法、アノテーションは正解ラベルを付ける作業で、いずれも探索の経験則ではない。", "usecase": "選択肢が多すぎて全部は調べられない探索(経路探索・ゲームAIなど)で、現実的な時間で良い答えに近づくために使う。", "opt": ["正解。経験則で良さそうな方を優先し効率化する目安がヒューリスティック。", "可能性を全部調べる総当たりで、経験則で絞る発想とは逆。", "ニューラルネットの学習手法で、探索の経験則ではない。", "正解ラベルを付ける作業で、探索の目安ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q7', '概念やその関係、用語の意味を、コンピュータが扱えるように体系立てて記述したものを指す語はどれか。', NULL, '["オントロジー", "データベース", "ヒストグラム", "ハイパーパラメータ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "概念や用語の意味・関係を体系立てて記述したものは？", "point": "「概念とその関係・意味を体系立てて記述したもの」なら、オントロジー。", "kid": "「犬は動物」「しっぽは犬の一部」のように、言葉の意味や関係をきちんと整理して、コンピュータが扱えるようにした知識の体系。", "eg": "分野の用語をきれいに整理した「概念の地図・辞書」のようなもの。", "terms": [["オントロジー", "概念やその関係、用語の意味を体系的に記述したもの。知識をコンピュータで扱う土台"], ["意味ネットワーク", "概念を関係の線でつないで表す、知識表現の一形態"]], "think": "「概念と関係・意味を体系立てて記述」ならオントロジー。単にデータを表に貯めるデータベースとは目的が違う。", "vs": "データベースはデータを整理して貯める仕組み、ヒストグラムはデータの分布を棒で見る図、ハイパーパラメータは人が決める設定値で、いずれも概念の意味体系ではない。", "usecase": "医療や検索など、用語の意味をそろえて機械に理解させたい分野で使う。知識をルール化する第2次ブームの中心テーマの一つ。", "opt": ["正解。概念や用語の意味・関係を体系立てて記述したのがオントロジー。", "データを整理して貯める仕組みで、概念の意味体系ではない。", "データの分布を棒で見る図で、知識の記述ではない。", "人が決める設定値で、概念の体系ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q8', '1980年代に日本が国家プロジェクトとして推進した、論理推論を高速に行うコンピュータの開発計画はどれか。', NULL, '["第五世代コンピュータ", "ダートマス会議", "ImageNet", "GPU"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "1980年代に日本が推進した、論理推論を高速化する国家プロジェクトは？", "point": "「1980年代・日本の国家プロジェクト・論理推論の高速化」なら、第五世代コンピュータ。", "kid": "1980年代に日本が国を挙げて取り組んだ、論理的な推論を高速に行うコンピュータを作る計画。当時は大きな期待を集めた。", "eg": "国が旗を振って「次世代の頭脳マシンを作ろう」と号令をかけた、あの一大プロジェクト。", "terms": [["第五世代コンピュータ", "1980年代に日本が推進した、論理推論を高速に行うコンピュータの国家開発計画"], ["第2次AIブーム", "知識をルール化するエキスパートシステムが盛んだった時期。この計画もその流れにある"]], "think": "「1980年代・日本・論理推論の国家計画」なら第五世代コンピュータ。AIの語源となったダートマス会議(1956年・米国)とは時代も国も違う。", "vs": "ダートマス会議は1956年にAIの語が生まれた会議、ImageNetは画像認識用の大規模データセット、GPUは並列計算が得意な演算装置で、いずれも日本の国家プロジェクトではない。", "usecase": "AIの歴史で、知識ベースのアプローチに大きく投資された時代の象徴。期待と現実のギャップ(ブームの浮沈)を学ぶ題材。", "opt": ["正解。1980年代に日本が推進した論理推論の国家プロジェクト。", "1956年にAIの語が生まれた会議で、日本の計画ではない。", "画像認識用の大規模データセットで、国家プロジェクトではない。", "並列計算が得意な演算装置で、開発計画そのものではない。"]}'::jsonb, 1
