SELECT s.id, c.id, 'g-kentei-c-q9', '2011年にアメリカのクイズ番組で人間のチャンピオンに勝利した、IBMの質問応答システムはどれか。', NULL, '["Watson", "MYCIN", "ELIZA", "Stable Diffusion"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "クイズ番組で人間王者に勝ったIBMの質問応答システムは？", "point": "「クイズ番組で人間チャンピオンに勝ったIBMの質問応答システム」なら、Watson。", "kid": "2011年、アメリカのクイズ番組で、膨大な知識から質問に答えて人間の王者を破ったIBMのシステム。自然な言葉の質問を理解して答えるのが特徴。", "eg": "早押しクイズで、人間の名人より速く正確に答えた“超物知りの回答マシン”。", "terms": [["Watson", "2011年にクイズ番組で人間チャンピオンに勝った、IBMの質問応答システム"], ["質問応答", "自然な言葉の質問を理解し、知識から答えを返すタスク"]], "think": "「クイズ番組・IBM・質問応答」ならWatson。感染症診断のMYCINや、おうむ返しのELIZAとは目的が違う。", "vs": "MYCINは感染症診断のエキスパートシステム、ELIZAはおうむ返しの対話プログラム、Stable Diffusionは画像生成AIで、いずれもクイズで人間に勝った質問応答システムではない。", "usecase": "大量の文書から答えを探す質問応答の実力を示した例。後に医療や企業の問い合わせ対応などへの応用が試みられた。", "opt": ["正解。クイズ番組で人間王者に勝ったIBMの質問応答システム。", "感染症診断のエキスパートシステムで、クイズの質問応答ではない。", "おうむ返しの対話プログラムで、質問応答システムではない。", "画像生成AIで、クイズに答えるシステムではない。"]}'::jsonb, 1
