SELECT s.id, c.id, 'g-kentei-c-q10', '2016年に囲碁のトップ棋士に勝利し、第3次AIブームを象徴する存在となった、ディープラーニングとモンテカルロ木探索を組み合わせたAIはどれか。', NULL, '["AlphaGo", "Deep Blue", "ELIZA", "BERT"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "2016年に囲碁のトップ棋士に勝った、深層学習と探索を組み合わせたAIは？", "point": "「2016年・囲碁でトップ棋士に勝利・深層学習＋モンテカルロ木探索」なら、AlphaGo。", "kid": "2016年、それまで難しいとされた囲碁で、世界トップ級の棋士に勝ったAI。盤面を見抜く目(ディープラーニング)と、先を読む探索(モンテカルロ木探索)を組み合わせている。", "eg": "「勘(深層学習で盤面を評価)」と「読み(探索で先を計算)」の両方を備えた、囲碁の超一流棋士。", "terms": [["AlphaGo", "2016年に囲碁のトップ棋士に勝ったAI。深層学習とモンテカルロ木探索を組み合わせた"], ["モンテカルロ木探索", "ランダムな試行を重ねて手の勝率を見積もる探索。AlphaGoの中核の一つ"]], "think": "「囲碁・2016年・深層学習＋探索」ならAlphaGo。チェスで勝ったDeep Blueは1997年で、囲碁でも手法も違う。", "vs": "Deep Blueは1997年にチェスで勝ったAI、ELIZAはおうむ返しの対話プログラム、BERTは文の意味を理解する言語モデルで、いずれも囲碁でトップ棋士に勝ったAlphaGoではない。", "usecase": "ディープラーニングの実力を世界に印象づけた出来事。強化学習と探索の組み合わせが、複雑な意思決定に有効だと示した。", "opt": ["正解。2016年に囲碁でトップ棋士に勝った深層学習＋探索のAI。", "1997年にチェスで勝ったAIで、囲碁のAlphaGoとは別。", "おうむ返しの対話プログラムで、囲碁AIではない。", "文の意味を理解する言語モデルで、囲碁で勝ったAIではない。"]}'::jsonb, 1
