SELECT s.id, c.id, 'g-kentei-c-q11', '気温から売上のように、連続する数値そのものを予測する教師あり学習のタスクはどれか。', NULL, '["回帰", "分類", "クラスタリング", "次元削減"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "連続する数値そのものを予測する教師あり学習は？", "point": "「連続した数値そのものを予測する」なら、回帰。", "kid": "「明日の気温は何度」「この家はいくら」のように、数値そのものを当てるのが回帰。「犬か猫か」のようにグループに振り分けるのは分類。", "eg": "体重計の目盛り（数値）を当てるのが回帰、通販の「S/M/L」を当てるのが分類。", "terms": [["回帰", "連続する数値そのものを予測する教師あり学習。売上や価格の予測など"], ["分類", "どのグループ(クラス)かを当てる教師あり学習。回帰と対になる"]], "think": "「数値そのものを当てる」なら回帰、「どのグループかを当てる」なら分類。出力が数値かグループかで見分ける。", "vs": "分類はグループを当てる、クラスタリングは正解なしでまとまりを作る教師なし、次元削減は項目を減らす手法で、いずれも数値そのものを予測する回帰ではない。", "usecase": "需要予測、価格推定、来店客数の見積もりなど、「いくつになるか」を当てたい場面で使う教師あり学習の基本。", "opt": ["正解。連続する数値そのものを予測するのが回帰。", "どのグループかを当てるタスクで、数値そのものの予測ではない。", "正解なしでまとまりを作る教師なしで、数値予測ではない。", "項目を減らす手法で、数値そのものの予測ではない。"]}'::jsonb, 1
