SELECT s.id, c.id, 'g-kentei-c-q13', 'データを、近いものどうしから順に少しずつまとめていき、まとまり方を樹形図（デンドログラム）で表す教師なしの手法はどれか。', NULL, '["階層的クラスタリング", "k-means法", "ロジスティック回帰", "主成分分析"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "近いものから順にまとめ、樹形図で表す教師なしの手法は？", "point": "「近いものから順にまとめ、樹形図で表す」なら、階層的クラスタリング。", "kid": "似たデータどうしを、一番近いペアから順にくっつけていって、まとまり方を枝分かれの図(樹形図)で表す。グループ数を最初に決めなくてよいのが特徴。", "eg": "家系図を逆にたどるように、近い個体から順に合流させて“系統図”を作るイメージ。", "terms": [["階層的クラスタリング", "近いものから順にまとめ、まとまり方を樹形図(デンドログラム)で表す教師なしの手法"], ["k-means法", "最初にグループ数kを決めて分ける、非階層的なクラスタリング"]], "think": "「近い順にまとめて樹形図」なら階層的クラスタリング。最初にグループ数を決めるk-meansとは分け方が違う。", "vs": "k-means法は最初にグループ数を決める非階層的な分け方、ロジスティック回帰は分類、主成分分析は次元削減で、いずれも樹形図で表す階層的クラスタリングではない。", "usecase": "グループ数が事前に分からないときに、まとまり方の全体像を樹形図で見たい場面で使う。遺伝子や顧客の分類などで役立つ。", "opt": ["正解。近いものから順にまとめ樹形図で表すのが階層的クラスタリング。", "最初にグループ数を決める非階層的な分け方で、樹形図は作らない。", "グループに振り分ける分類で、まとまりを作る教師なしではない。", "項目を減らす次元削減で、クラスタリングではない。"]}'::jsonb, 1
