SELECT s.id, c.id, 'g-kentei-c-q14', '数十次元のような高次元データを、点どうしの近さを保ったまま2次元の散布図に落として可視化する手法はどれか。', NULL, '["t-SNE", "線形回帰", "ブースティング", "アノテーション"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "高次元データを、近さを保って2次元に落として可視化する手法は？", "point": "「高次元データを近さを保って2次元に落として見える化する」なら、t-SNE。", "kid": "何十個もの項目を持つデータは、そのままでは絵にできない。t-SNEは、近いデータが近くに来るよう工夫して2次元の散布図に落とし、かたまり(クラスタ)を目で見えるようにする。", "eg": "立体的な模型を、影絵のように平面に写しても“近いものは近く”見えるように工夫して投影する、あのイメージ。", "terms": [["t-SNE", "高次元データを、点どうしの近さを保ちつつ2次元などに落として可視化する手法"], ["次元削減", "項目(次元)を減らす手法の総称。t-SNEは可視化に特化した一種"]], "think": "「高次元を2次元にして可視化・近さを保つ」ならt-SNE。数値を予測する回帰や、モデルを束ねるブースティングとは目的が違う。", "vs": "線形回帰は数値を予測する手法、ブースティングは学習器を順に足す手法、アノテーションは正解ラベルを付ける作業で、いずれも高次元の可視化手法ではない。", "usecase": "学習したデータや特徴量が、うまくグループに分かれているかを目で確かめたいときに使う。分析結果の見える化に役立つ。", "opt": ["正解。高次元データを近さを保って2次元に落として可視化するのがt-SNE。", "数値を予測する手法で、可視化のための次元削減ではない。", "学習器を順に足す手法で、可視化ではない。", "正解ラベルを付ける作業で、可視化手法ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='3. 機械学習の概要'
