SELECT s.id, c.id, 'g-kentei-c-q20', '最適化で、前回までの更新方向の「勢い」を引き継ぐことで、揺れを抑えつつ谷底へ速く進めるようにする工夫はどれか。', NULL, '["モメンタム", "ドロップアウト", "バッチ正規化", "早期終了"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "前回までの更新方向の勢いを引き継いで、揺れを抑え速く進める工夫は？", "point": "「前の更新の勢いを引き継いで、揺れを抑え速く収束させる」なら、モメンタム。", "kid": "学習は坂を下るイメージ。毎回まっさらに方向を決めると左右に揺れて遅い。前に進んだ勢いを引き継ぐと、揺れが打ち消され、谷底へまっすぐ速く進める。この工夫がモメンタム。", "eg": "自転車で一度こぎ出すと勢いがついて、少しの力でスイスイ進む、あの慣性。", "terms": [["モメンタム", "前回までの更新方向の勢いを引き継ぎ、揺れを抑えて収束を速める最適化の工夫"], ["Adam", "モメンタムと、方向ごとの歩幅調整(RMSProp)を組み合わせた最適化"]], "think": "「前の勢いを引き継いで揺れを抑え速く進む」ならモメンタム。ノードを休ませるドロップアウトや、値をそろえるバッチ正規化とは目的が違う。", "vs": "ドロップアウトはノードを休ませる過学習対策、バッチ正規化は各層の値をそろえる手法、早期終了は学習を途中で止める手法で、いずれも勢いを引き継ぐモメンタムではない。", "usecase": "学習が左右に揺れてなかなか収束しないときに効く。単体でも使うが、Adamの部品としても広く使われる。", "opt": ["正解。前の更新の勢いを引き継いで揺れを抑え速く進むのがモメンタム。", "ノードを休ませる過学習対策で、勢いを引き継ぐ工夫ではない。", "各層の値をそろえる手法で、勢いの話ではない。", "学習を途中で止める手法で、モメンタムではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='4. ディープラーニングの概要'
