SELECT s.id, c.id, 'g-kentei-c-q21', '最適化で、本当の最小ではないのに、まわりより低いために「そこが底だ」と勘違いして止まってしまう地点はどれか。', NULL, '["局所最適解", "大域最適解", "過学習", "活性化関数"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "本当の最小ではないのに、まわりより低くて止まってしまう地点は？", "point": "「本当の最小ではないのに、まわりより低くてはまり込む谷」なら、局所最適解。", "kid": "学習は「一番低い谷(最小)」を目指して坂を下る。でも、途中の小さなくぼみ(まわりより低い場所)に落ちると、そこが底だと勘違いして止まってしまう。この小さなくぼみが局所最適解。", "eg": "山下りで、本当の谷底(大域最適解)に着く前に、途中の小さなくぼみにはまって動けなくなる、あの状態。", "terms": [["局所最適解", "本当の最小ではないが、まわりより低いために止まってしまう地点"], ["大域最適解", "全体の中で本当に一番低い、目指すべき最小の地点"]], "think": "「まわりより低いだけの偽の底」なら局所最適解。全体で本当に一番低い大域最適解と区別する。", "vs": "大域最適解は本当に一番低い地点、過学習は訓練に合わせすぎる問題、活性化関数はノードで値を変換する部品で、いずれも「偽の底」を指す局所最適解ではない。", "usecase": "学習が途中の悪い所で止まる原因の一つ。勢いをつけるモメンタムやランダム性を持つSGDが、こうしたくぼみから抜けるのに役立つ。", "opt": ["正解。まわりより低いだけで、本当の最小ではない地点が局所最適解。", "全体で本当に一番低い目指すべき地点で、偽の底ではない。", "訓練に合わせすぎる問題で、最適化の地点の話ではない。", "ノードで値を変換する部品で、最適化の地点ではない。"]}'::jsonb, 1
