SELECT s.id, c.id, 'g-kentei-c-q22', '深いネットワークで学習の勾配が層を伝わるうちに大きくなりすぎて発散するのを防ぐため、勾配を一定の大きさで頭打ちにする手法はどれか。', NULL, '["勾配クリッピング", "ドロップアウト", "データ拡張", "アノテーション"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "勾配が大きくなりすぎて発散するのを、頭打ちにして防ぐ手法は？", "point": "「勾配が大きくなりすぎるのを一定値で頭打ちにする」なら、勾配クリッピング。", "kid": "学習の「直してね」の合図(勾配)が、層を伝わるうちに逆に大きくなりすぎると、値が振れて壊れる(勾配爆発)。そこで合図の大きさに上限を設けて頭打ちにするのが勾配クリッピング。", "eg": "音量が急に爆音になるのを、リミッターで上限を決めて抑える、あの仕組み。", "terms": [["勾配クリッピング", "勾配が大きくなりすぎたとき、一定の大きさで頭打ちにして発散を防ぐ手法"], ["勾配爆発", "勾配が層を伝わるうちに大きくなりすぎて、学習が発散してしまう問題"]], "think": "「勾配が大きくなりすぎるのを頭打ち」なら勾配クリッピング。勾配が消える勾配消失とは逆の問題への対処。", "vs": "ドロップアウトはノードを休ませる過学習対策、データ拡張はデータの水増し、アノテーションは正解ラベル付けで、いずれも勾配を頭打ちにする手法ではない。", "usecase": "RNNなど勾配が爆発しやすいネットワークの学習を安定させるのに使う。学習中に損失が突然跳ね上がるときの対処法。", "opt": ["正解。勾配を一定値で頭打ちにして発散を防ぐのが勾配クリッピング。", "ノードを休ませる過学習対策で、勾配の頭打ちではない。", "データを水増しする手法で、勾配の頭打ちではない。", "正解ラベルを付ける作業で、勾配の話ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='4. ディープラーニングの概要'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q23', '学習の過程で自動的に決まる重みとは違い、学習を始める前に人が決めておく設定値（学習率や層の数など）を指す語はどれか。', NULL, '["ハイパーパラメータ", "パラメータ（重み）", "損失関数", "活性化関数"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "学習前に人が決めておく設定値(学習率や層の数など)を指す語は？", "point": "「学習で自動調整されず、人が事前に決める設定値」なら、ハイパーパラメータ。", "kid": "重み(パラメータ)は学習の中で自動的に決まっていく。一方、学習率や層の数などは、学習を始める前に人が決めておく必要がある。この“人が決める設定値”がハイパーパラメータ。", "eg": "料理でいえば、火加減や時間(人が決める設定＝ハイパーパラメータ)と、出来上がった味(自動的に決まる結果＝パラメータ)の違い。", "terms": [["ハイパーパラメータ", "学習で自動調整されず、人が事前に決める設定値。学習率・層の数・バッチサイズなど"], ["パラメータ（重み）", "学習の過程で自動的に決まっていく値"]], "think": "「人が事前に決める設定値」ならハイパーパラメータ。学習の中で自動的に決まる重み(パラメータ)と対で押さえる。", "vs": "パラメータ(重み)は学習で自動的に決まる値、損失関数は誤差を測る関数、活性化関数はノードで値を変換する部品で、いずれも人が事前に決める設定値そのものではない。", "usecase": "グリッドサーチなどで調整する対象。良い設定値を選べるかどうかがモデルの性能を左右するので、調整の勘所になる。", "opt": ["正解。人が事前に決める設定値がハイパーパラメータ。", "学習の中で自動的に決まる値で、人が事前に決める設定ではない。", "誤差を測る関数で、設定値そのものではない。", "ノードで値を変換する部品で、設定値ではない。"]}'::jsonb, 1
