INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q24', 'データを圧縮する際に、その特徴を「確率的な分布」として捉えることで、学習した特徴から新しいデータも生成できるようにしたオートエンコーダの発展形はどれか。', NULL, '["変分オートエンコーダ", "GAN", "word2vec", "決定木"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "特徴を確率分布として捉え、新しいデータも生成できるオートエンコーダの発展形は？", "point": "「特徴を確率分布で捉え、新データも生成できるオートエンコーダ」なら、変分オートエンコーダ(VAE)。", "kid": "ふつうのオートエンコーダは圧縮して復元するだけ。VAEは、圧縮した特徴を“確率のばらつき”として扱うので、その分布から少しずらして新しいデータ(似た画像など)を作り出せる。", "eg": "顔の特徴を「平均＋ばらつき」で覚えておき、そこから少し変えて“実在しない別の顔”を作れる、あのイメージ。", "terms": [["変分オートエンコーダ（VAE）", "特徴を確率分布として捉え、そこから新しいデータも生成できるオートエンコーダの発展形"], ["オートエンコーダ", "入力を圧縮し復元するよう学ぶネットワーク。VAEはその生成向けの発展形"]], "think": "「圧縮＋確率分布＋生成できる」ならVAE。生成器と識別器を競わせるGANとは、生成の仕組みが違う。", "vs": "GANは生成器と識別器を競わせる別の生成モデル、word2vecは単語をベクトルにする手法、決定木は条件分岐で予測する手法で、いずれも確率分布で生成するVAEではない。", "usecase": "画像などの生成や、異常検知(分布から外れるものを見つける)に使う。GANと並ぶ代表的な生成モデルの一つ。", "opt": ["正解。特徴を確率分布で捉え新データも生成できるのがVAE。", "生成器と識別器を競わせる別の生成モデルで、VAEとは仕組みが違う。", "単語をベクトルにする手法で、生成モデルではない。", "条件分岐で予測する手法で、生成モデルではない。"]}'::jsonb, 1
