SELECT s.id, c.id, 'g-kentei-c-q28', '系列を前からだけでなく後ろからも読み、ある時点の判断に「前後両方の文脈」を使えるようにしたRNNはどれか。', NULL, '["双方向RNN", "単方向RNN", "畳み込みネットワーク", "オートエンコーダ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "前からと後ろからの両方向で系列を読み、前後の文脈を使えるRNNは？", "point": "「前からと後ろからの両方向で読み、前後の文脈を使う」なら、双方向RNN。", "kid": "ふつうのRNNは前から順にしか読まないので、ある単語の判断に“後ろの文脈”を使えない。双方向RNNは後ろからも読む向きを足し、前後両方の文脈を合わせて判断できる。", "eg": "穴埋め問題を、前の文だけでなく後ろの文も読んでから答える、あの解き方。", "terms": [["双方向RNN", "系列を前からと後ろからの両方向で読み、前後の文脈を使えるようにしたRNN"], ["単方向RNN", "前から一方向にしか読まない通常のRNN。後ろの文脈は使えない"]], "think": "「前後の両方向で読む」なら双方向RNN。前からしか読まない単方向RNNの弱点(後ろの文脈が使えない)を補う。", "vs": "単方向RNNは前からしか読まない、畳み込みネットワークは画像の局所特徴を拾う、オートエンコーダは圧縮して復元を学ぶ構造で、いずれも前後両方向で読む双方向RNNではない。", "usecase": "文全体を見て判断する固有表現抽出や品詞付けなど、後ろの文脈も効くタスクで精度が上がる。", "opt": ["正解。前後の両方向で読み前後の文脈を使えるのが双方向RNN。", "前から一方向にしか読まず、後ろの文脈を使えない通常のRNN。", "画像の局所特徴を拾う手法で、双方向のRNNではない。", "圧縮して復元を学ぶ構造で、双方向RNNではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='5. ディープラーニングの要素技術'
