SELECT s.id, c.id, 'g-kentei-c-q30', '画像や動画から、人の関節（肩・肘・膝など）の位置を推定し、体の姿勢をとらえるタスクはどれか。', NULL, '["姿勢推定", "画像分類", "物体検出", "異常検知"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "人の関節の位置を推定して、体の姿勢をとらえるタスクは？", "point": "「人の関節の位置を推定して姿勢をとらえる」なら、姿勢推定。", "kid": "画像や動画から、肩・肘・膝といった関節がどこにあるかを点で当て、体がどんな姿勢かをとらえるタスク。棒人間の骨組みを描くようなイメージ。", "eg": "ダンスの動きを、関節に印を付けて“棒人間”として再現する、あの見立て。", "terms": [["姿勢推定", "画像や動画から人の関節の位置を推定し、体の姿勢をとらえるタスク"], ["物体検出", "物の種類と位置を枠で囲むタスク。関節点を出す姿勢推定とは出力が違う"]], "think": "「関節の位置・姿勢をとらえる」なら姿勢推定。写真全体に1ラベルの画像分類や、枠で囲む物体検出とは出力が違う。", "vs": "画像分類は写真全体に1ラベル、物体検出は種類と位置を枠で囲む、異常検知は普段と違うものを見つけるタスクで、いずれも関節点を出す姿勢推定ではない。", "usecase": "スポーツのフォーム解析、転倒検知、モーションキャプチャ、ジェスチャー操作などで使う。", "opt": ["正解。人の関節の位置を推定して姿勢をとらえるのが姿勢推定。", "写真全体に1ラベルを付けるタスクで、関節の位置は出さない。", "種類と位置を枠で囲むタスクで、関節点を出すものではない。", "普段と違うものを見つけるタスクで、姿勢推定ではない。"]}'::jsonb, 1
