SELECT s.id, c.id, 'g-kentei-c-q31', '画像を画素単位で塗り分けるだけでなく、同じ「人」でも一人ひとりを別個体として区別して領域を分けるタスクはどれか。', NULL, '["インスタンスセグメンテーション", "セマンティックセグメンテーション", "画像分類", "姿勢推定"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画素を塗り分けつつ、同じ種類でも個体ごとに区別するタスクは？", "point": "「画素を塗り分け、かつ同じ種類でも個体ごとに区別する」なら、インスタンスセグメンテーション。", "kid": "「これは人、これは道路」と画素ごとに塗り分けるのがセマンティックセグメンテーション。そこからさらに「1人目・2人目」と個体まで分けるのがインスタンスセグメンテーション。より細かい。", "eg": "集合写真で、全員を「人」の色で塗るだけでなく、一人ひとりを別の色で塗り分ける、あの細かさ。", "terms": [["インスタンスセグメンテーション", "画素を塗り分けたうえで、同じ種類でも個体ごとに区別して領域を分けるタスク"], ["セマンティックセグメンテーション", "画素ごとにクラスを塗り分けるが、同じ種類の個体は区別しないタスク"]], "think": "「塗り分け＋個体の区別」ならインスタンスセグメンテーション。個体を区別しないセマンティックセグメンテーションより細かい。", "vs": "セマンティックセグメンテーションは個体を区別せず塗り分けるだけ、画像分類は写真全体に1ラベル、姿勢推定は関節の位置を当てるタスクで、いずれも個体まで分けるインスタンスセグメンテーションではない。", "usecase": "混み合った場面で人や物を一つずつ数えたい・追跡したいときに使う。自動運転や店舗の人数把握などで役立つ。", "opt": ["正解。画素を塗り分け、かつ個体ごとに区別するのがインスタンスセグメンテーション。", "画素を塗り分けるが、同じ種類の個体は区別しない。", "写真全体に1ラベルを付けるだけで、画素の塗り分けではない。", "関節の位置を当てるタスクで、領域の塗り分けではない。"]}'::jsonb, 1
