SELECT s.id, c.id, 'g-kentei-c-q33', '画像を入力として、その内容を説明する文章を自動で作り出すタスクはどれか。', NULL, '["画像キャプション生成", "画像スタイル変換", "セマンティックセグメンテーション", "超解像"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画像を入力に、その内容を説明する文章を作るタスクは？", "point": "「画像を見て、その内容を説明する文章を作る」なら、画像キャプション生成。", "kid": "写真を入れると「犬が芝生で走っている」のような説明文を自動で作るタスク。画像を見る力(CNN)と文を書く力(RNN/Transformer)を組み合わせる。", "eg": "目の見えない人に写真の内容を言葉で伝える、あの説明を自動化したもの。", "terms": [["画像キャプション生成", "画像を入力に、その内容を説明する文章を生成するタスク。画像認識と言語生成の組み合わせ"], ["マルチモーダル", "画像と言葉など種類の違う情報を扱うこと。画像キャプション生成もその一種"]], "think": "「画像→説明文を作る」なら画像キャプション生成。画像を加工・変換する他のタスクとは、出力が“文章”である点が違う。", "vs": "画像スタイル変換は絵柄を別の画風に変える、セマンティックセグメンテーションは画素を塗り分ける、超解像は画像を高解像度化するタスクで、いずれも説明文を作る画像キャプション生成ではない。", "usecase": "画像の自動タグ付け、視覚障害者向けの読み上げ、大量画像の検索用テキスト付けなどで役立つ。", "opt": ["正解。画像を見て説明文を作るのが画像キャプション生成。", "絵柄を別の画風に変えるタスクで、説明文は作らない。", "画素を塗り分けるタスクで、文章を作るものではない。", "画像を高解像度化するタスクで、説明文の生成ではない。"]}'::jsonb, 1
