INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q35', '大量の正常なデータのパターンを学び、そこから大きく外れるものを「異常」として見つけ出す仕組みはどれか。', NULL, '["異常検知", "画像分類", "感情分析", "データ拡張"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "正常なパターンから大きく外れるものを見つけ出す仕組みは？", "point": "「正常のパターンを学び、そこから大きく外れるものを見つける」なら、異常検知。", "kid": "普段の正常な状態をたくさん学んでおき、それと大きく違うものが来たら「おかしい」と気づく仕組み。異常なデータは少なくてよく、正常データだけでも学べるのが利点。", "eg": "いつもの体調を知っている人が、少しの変化で「今日はおかしい」と気づく、あの感覚。", "terms": [["異常検知", "正常なデータのパターンを学び、そこから大きく外れるものを異常として見つける仕組み"], ["オートエンコーダ", "正常データを圧縮・復元するよう学び、うまく復元できないものを異常とする代表手法"]], "think": "「正常を学んで、外れるものを見つける」なら異常検知。あらかじめ全種類を教える画像分類とは違い、異常の例が少なくても使える。", "vs": "画像分類は写真全体に1ラベルを付ける、感情分析は文章の気持ちを判定する、データ拡張はデータを水増しする手法で、いずれも外れ値を見つける異常検知ではない。", "usecase": "工場の設備故障の予兆、クレジットカードの不正利用、ネットワークの侵入検知など、「めったに起きない異常」を捉えたい場面で使う。", "opt": ["正解。正常のパターンから外れるものを見つけるのが異常検知。", "写真全体に1ラベルを付けるタスクで、外れ値を見つけるものではない。", "文章の気持ちを判定するタスクで、異常検知ではない。", "データを水増しする手法で、異常検知ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='6. ディープラーニングの応用例'
