SELECT s.id, c.id, 'g-kentei-c-q36', '生成AIの出力に対して人間が「どちらが好ましいか」を評価し、その好みに沿うようにモデルを調整する手法はどれか。', NULL, '["RLHF", "教師なし事前学習", "バッチ正規化", "データ拡張"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "人間の好みの評価に沿うよう、生成AIを調整する手法は？", "point": "「人間の好みの評価を報酬にして、生成AIを人に沿うよう調整する」なら、RLHF。", "kid": "生成AIの答えを人間が「こっちが好ましい」と評価し、その好みを“ごほうび”にして調整する。これで、事実として正しいだけでなく、人にとって使いやすい・安全な答えに近づく。", "eg": "弟子の受け答えに師匠が「そっちの方がいい」と好みを伝え続け、師匠好みに仕上げていく、あの育て方。", "terms": [["RLHF", "人間のフィードバック(好みの評価)を報酬にして、生成AIを人の好みに沿うよう調整する手法"], ["強化学習", "報酬を手がかりに試行錯誤で行動を学ぶ方法。RLHFの土台"]], "think": "「人間の好みを報酬に調整」ならRLHF。データを増やすデータ拡張や、広く学ぶ事前学習とは目的が違う。", "vs": "教師なし事前学習は正解なしで広く学ぶ段階、バッチ正規化は各層の値をそろえる手法、データ拡張はデータの水増しで、いずれも人間の好みで調整するRLHFではない。", "usecase": "ChatGPTなどの対話AIを、より役立ち・安全で・人に沿った応答にするために使われた重要な仕上げ工程。", "opt": ["正解。人間の好みの評価を報酬にして生成AIを調整するのがRLHF。", "正解なしで広く学ぶ事前学習の段階で、好みで調整する工程ではない。", "各層の値をそろえる手法で、RLHFではない。", "データを水増しする手法で、好みで調整するものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='6. ディープラーニングの応用例'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q37', '生のデータから、予測に効きやすい項目（例：日付から「曜日」や「祝日か」を作る）を人が設計・加工する作業はどれか。', NULL, '["特徴量エンジニアリング", "ハイパーパラメータ探索", "データ拡張", "デプロイ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "予測に効く項目を、生データから人が設計・加工する作業は？", "point": "「予測に効く項目を、生データから人が設計・加工する」なら、特徴量エンジニアリング。", "kid": "生のデータをそのまま使うより、「日付から曜日や祝日を取り出す」など、予測に効きそうな項目を人が工夫して作る方が精度が上がる。この“項目づくり”が特徴量エンジニアリング。", "eg": "料理で、素材をそのまま出すより、下ごしらえで切り方や下味を工夫すると味が引き立つ、あの手間。", "terms": [["特徴量エンジニアリング", "生データから予測に効く項目(特徴量)を人が設計・加工する作業"], ["特徴表現学習", "特徴量そのものを自動で学ぶディープラーニングの段階。人手の設計を減らす"]], "think": "「予測に効く項目を人が作る」なら特徴量エンジニアリング。設定値を探すハイパーパラメータ探索や、データを増やすデータ拡張とは目的が違う。", "vs": "ハイパーパラメータ探索は設定値を探す作業、データ拡張はデータを水増しする手法、デプロイはモデルを本番で動かすことで、いずれも項目を設計する特徴量エンジニアリングではない。", "usecase": "表形式データの機械学習で精度を左右する重要工程。良い特徴を作れるかどうかが結果を大きく変える(ディープラーニングでは自動化が進む領域)。", "opt": ["正解。予測に効く項目を生データから設計・加工するのが特徴量エンジニアリング。", "設定値を探す作業で、項目を設計するものではない。", "データを水増しする手法で、項目づくりではない。", "モデルを本番で動かすことで、特徴量の設計ではない。"]}'::jsonb, 1
