WHERE s.slug='g-kentei-c' AND c.name='7. AIの社会実装に向けて'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q38', '運用しているうちに世の中の傾向やデータの性質が変化し、以前は正確だったモデルの精度がだんだん落ちていく現象はどれか。', NULL, '["コンセプトドリフト", "過学習", "勾配消失", "データ拡張"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "時間とともにデータの傾向が変わり、モデルの精度が落ちていく現象は？", "point": "「運用中に世の中やデータの傾向が変わり、モデルが当たらなくなる」なら、コンセプトドリフト。", "kid": "モデルは作った時点のデータに合わせて学ぶ。でも世の中の流行や状況は変わるので、時間が経つと当時の“正解”が今の実態とずれ、精度がだんだん落ちる。この“ずれていく”現象。", "eg": "去年のヒット予測が、流行が変わった今年には当たらなくなる、あの時代遅れ。", "terms": [["コンセプトドリフト", "時間とともにデータの傾向が変化し、以前は正確だったモデルの精度が落ちていく現象"], ["再学習", "新しいデータでモデルを学習し直すこと。コンセプトドリフトへの対処"]], "think": "「運用中に傾向が変わって精度が落ちる」ならコンセプトドリフト。作った時点で訓練に合わせすぎる過学習とは、原因も時間軸も違う。", "vs": "過学習は訓練データに合わせすぎる問題、勾配消失は深い層で学習の信号が消える問題、データ拡張はデータの水増しで、いずれも時間とともにずれるコンセプトドリフトではない。", "usecase": "「本番のモデルを定期的に監視し、精度が落ちたら再学習する」というMLOpsの必要性の根拠。運用を続ける限りつきまとう課題。", "opt": ["正解。時間とともに傾向が変わり精度が落ちるのがコンセプトドリフト。", "訓練データに合わせすぎる問題で、時間による劣化とは別。", "深い層で学習の信号が消える問題で、この現象とは違う。", "データを水増しする手法で、精度が落ちる現象ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='7. AIの社会実装に向けて'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
