SELECT s.id, c.id, 'g-kentei-c-q39', '誰でも自由に使い、再配布や加工もできる形で公開されているデータを指す語はどれか。', NULL, '["オープンデータ", "アノテーション", "データリーケージ", "メタデータ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "誰でも自由に使え、再配布や加工もできる公開データを指す語は？", "point": "「誰でも自由に使い、加工・再配布もできる形で公開されたデータ」なら、オープンデータ。", "kid": "国や自治体、企業などが「誰でも自由に使っていいですよ」と公開しているデータ。使うだけでなく、加工や再配布もできるのが特徴。", "eg": "図書館の本のように、誰でも借りて使える“みんなのための”データ。", "terms": [["オープンデータ", "誰でも自由に使い、再配布や加工もできる形で公開されたデータ"], ["アノテーション", "データに正解ラベルを付ける作業。集めたデータを学習用に加工する工程"]], "think": "「誰でも自由に使える公開データ」ならオープンデータ。正解ラベルを付ける作業のアノテーションとは別のもの。", "vs": "アノテーションは正解ラベルを付ける作業、データリーケージは答えが訓練に漏れる問題、メタデータはデータの説明情報(いつ・誰が等)で、いずれも自由に使える公開データのオープンデータではない。", "usecase": "自前のデータが足りないときに、学習や分析の材料として活用できる。行政の統計や地図データなどが代表例。", "opt": ["正解。誰でも自由に使え加工・再配布できる公開データがオープンデータ。", "正解ラベルを付ける作業で、公開データそのものではない。", "答えが訓練に漏れる問題で、データの種類ではない。", "データの説明情報で、公開データそのものではない。"]}'::jsonb, 1
