INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q40', '100人中1人だけが陽性の検査で、全員を「陰性」と答えるだけのモデルでも正解率は99%になる。この例が示す注意点はどれか。', NULL, '["クラスが偏ると、正解率は実力を過大に見せうる", "正解率は、どんなデータでも実力を正しく表す", "正解率が高ければ、見落としも必ず少ない", "正解率は、回帰の予測にだけ使う指標だ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "全員を陰性と答えても正解率99%になる例が示す注意点は？", "point": "「クラスが偏ると、正解率だけでは実力を過大に見せる」ことに注意。", "kid": "100人中1人だけ陽性なら、全員「陰性」と答えるだけで99%当たる。でもこのモデルは陽性を1人も見つけられていない。正解率は、偏ったデータでは“優秀に見える罠”がある。", "eg": "ほとんど晴れの地域で「毎日晴れ」と予報すれば的中率は高いが、肝心の雨の日は当てられない、あの見かけ倒し。", "terms": [["正解率（Accuracy）", "全体のうち正しく判定できた割合。クラスが偏ると誤解を招きやすい"], ["適合率・再現率", "偏ったデータでも実力を測れる指標。正解率の弱点を補う"]], "think": "「偏ったデータでは正解率が高くても実力とは限らない」が要点。こういう場面では適合率・再現率やF値で測る。", "vs": "「どんなデータでも正しく表す」は誤りで偏りに弱い、「高ければ見落としも少ない」も誤りで見落としだらけでも高くなりうる、「回帰にだけ使う」も誤りで正解率は分類の指標。", "usecase": "不正検知や病気の検査など、陽性がまれな不均衡データの評価で必須の注意。正解率だけを見て安心しないための基本。", "opt": ["正解。クラスが偏ると正解率は実力を過大に見せうる。", "偏ったデータでは誤解を招くので、常に正しく表すとはいえない。", "見落としだらけでも正解率は高くなりうるので、誤り。", "正解率は分類の指標で、回帰専用ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q41', 'データが平均のまわりにどれだけ散らばっているかの大きさを表す指標はどれか。', NULL, '["標準偏差", "中央値", "相関係数", "最頻値"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "データが平均のまわりにどれだけ散らばっているかを表す指標は？", "point": "「平均からの散らばりの大きさ」を表すなら、標準偏差(や分散)。", "kid": "同じ平均点でも、みんなが平均近くに固まっているか、上下に大きくばらけているかは違う。その“ばらけ具合”の大きさを表すのが標準偏差(その二乗が分散)。", "eg": "的当てで、矢が中心近くに集まっているか、広く散らばっているか。その散らばり具合を数値にしたもの。", "terms": [["標準偏差", "データが平均からどれだけ散らばっているかを表す指標。分散の平方根"], ["分散", "散らばりを表すもう一つの指標。標準偏差を二乗した値"]], "think": "「平均からの散らばりの大きさ」なら標準偏差・分散。真ん中を表す中央値や、関係の強さを表す相関係数とは測るものが違う。", "vs": "中央値は真ん中の値、相関係数は2つの量の関係の強さ、最頻値は最も多く現れる値で、いずれも散らばりの大きさを表す標準偏差ではない。", "usecase": "品質のばらつき管理や、正規分布の68-95-99.7則(平均±1σに約68%)など、データの安定度・外れ値の判断の土台になる。", "opt": ["正解。平均からの散らばりの大きさを表すのが標準偏差。", "真ん中の値を表す指標で、散らばりの大きさではない。", "2つの量の関係の強さを表す指標で、散らばりではない。", "最も多く現れる値で、散らばりの大きさではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q42', '「もともとの確率」に「新しく得られた証拠」を反映して、確率を更新していく考え方はどれか。', NULL, '["ベイズの定理", "正規分布", "中心極限定理", "大数の法則"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "もとの確率に新しい証拠を反映して、確率を更新する考え方は？", "point": "「もとの確率を、新しい証拠で更新していく」考え方なら、ベイズの定理。", "kid": "最初に持っている見込み(事前確率)に、新しく分かった手がかり(証拠)を反映して、見込みを更新する(事後確率)。証拠が増えるほど、より確からしい確率に近づく。", "eg": "「たぶん風邪」と思っていたところに検査結果が出て、「やっぱり風邪の可能性が高い」と見込みを更新する、あの考え方。", "terms": [["ベイズの定理", "もとの確率(事前確率)に新しい証拠を反映して、更新後の確率(事後確率)を求める考え方"], ["事前確率／事後確率", "証拠を得る前の見込みと、得た後に更新した見込み"]], "think": "「もとの確率を証拠で更新」ならベイズの定理。データの分布を表す正規分布などとは、扱っているものが違う。", "vs": "正規分布はデータのばらつきの形、中心極限定理は平均の分布が正規分布に近づく法則、大数の法則は試行を重ねると割合が理論値に近づく法則で、いずれも確率を更新するベイズの定理ではない。", "usecase": "迷惑メール判定(ナイーブベイズ)や、証拠を積み重ねて診断・推定する場面で使う。データが増えるたびに判断を更新する土台。", "opt": ["正解。もとの確率を新しい証拠で更新するのがベイズの定理。", "データのばらつきの形を表す分布で、確率の更新の考え方ではない。", "平均の分布が正規分布に近づく法則で、更新の考え方ではない。", "試行を重ねると割合が理論値に近づく法則で、ベイズの定理ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q43', '2つの量の「直線的な関係の強さと向き」を、-1から+1の範囲の数値で表す指標はどれか。', NULL, '["相関係数", "標準偏差", "決定木", "混同行列"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "2つの量の直線的な関係の強さを-1〜+1で表す指標は？", "point": "「2つの量の直線的な関係の強さと向きを-1〜+1で表す」なら、相関係数。", "kid": "一方が増えると他方も増える(正の関係)か、減る(負の関係)か、その強さを-1〜+1の数値で表す。+1に近いほど右上がり、-1に近いほど右下がり、0に近いと関係が弱い。", "eg": "気温とアイスの売上のように「一緒に動くか」を一つの数値で表した、関係の強さのものさし。", "terms": [["相関係数", "2つの量の直線的な関係の強さと向きを-1〜+1で表す指標"], ["相関と因果", "相関があっても、一方が他方の原因とは限らない点に注意"]], "think": "「2つの量の関係の強さを-1〜+1で」なら相関係数。ただし相関が強くても、それが原因-結果(因果)とは限らない点に注意。", "vs": "標準偏差は散らばりの大きさ、決定木は条件分岐で予測する手法、混同行列は分類結果の集計表で、いずれも2つの量の関係の強さを表す相関係数ではない。", "usecase": "どの項目が予測に効きそうかの目星をつけたり、似た動きをする項目を見つけたりするのに使う。因果と混同しないのが肝心。", "opt": ["正解。2つの量の関係の強さと向きを-1〜+1で表すのが相関係数。", "データの散らばりの大きさを表す指標で、2量の関係ではない。", "条件分岐で予測する手法で、関係の強さの指標ではない。", "分類結果の集計表で、相関の指標ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q44', '生成AIに簡単な指示（プロンプト）を与えて出力させた画像の著作権について、現状の考え方として最も適切なものはどれか。', NULL, '["人の創作的な関与が乏しいと、著作物と認められにくい", "出力した瞬間に、必ず利用者の著作物になる", "AIの開発会社に、自動的に著作権が帰属する", "生成物には一切の権利が発生しないと法律にある"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "プロンプトで出させた生成物の著作権について、現状の考え方は？", "point": "「人の創作的な関与が乏しいと、生成物は著作物と認められにくい」。", "kid": "著作権は「人が創作的に表現したもの」を守る仕組み。簡単な指示を入れただけで出た生成物は、人の創作の工夫が乏しいと見なされやすく、著作物として保護されにくい。", "eg": "自動販売機のボタンを押して出てきた飲み物に、押した人の“作品”としての権利は生まれない、あの感覚に近い。", "terms": [["著作物", "人が思想や感情を創作的に表現したもの。著作権で保護される対象"], ["創作的寄与", "人がどれだけ創作的に関わったか。生成物の著作物性を判断する鍵"]], "think": "判断の軸は「人の創作的な関与があるか」。指示を入れただけでは関与が乏しく、著作物と認められにくい。会社への自動帰属や一律発生といった決めつけは誤り。", "vs": "「必ず利用者のもの」「開発会社に自動帰属」は決めつけで誤り、「一切権利が発生しないと法律に明記」も誤りで、人の創作的関与の程度で個別に判断される。", "usecase": "生成AIで作ったコンテンツを商用利用・権利主張したいときの前提知識。関与の度合いによって扱いが変わる、と押さえておく。", "opt": ["正解。人の創作的な関与が乏しいと著作物と認められにくい。", "出力しただけで必ず利用者のものになるとはいえず、決めつけは誤り。", "開発会社に自動帰属するというのも決めつけで、誤り。", "一律に権利が発生しないと法律に明記されているわけではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q45', '会員などの特定の相手に提供するために、一定の管理のもとで蓄積されたデータを、不正な取得や使用から守る不正競争防止法上の枠組みはどれか。', NULL, '["限定提供データ", "営業秘密", "特許権", "著作権"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "特定の相手に提供する、管理されたデータを守る不正競争防止法の枠組みは？", "point": "「特定の相手に提供する、管理された有用なデータを守る枠組み」なら、限定提供データ。", "kid": "「秘密」とまではいかないが、会員など決まった相手にだけ提供するために管理して蓄積したデータ。これを勝手に取得・使用されないよう守るのが、不正競争防止法の限定提供データ。", "eg": "会員限定で配布する有料データベースを、部外者が抜き取って悪用するのを法律で止められる、あの仕組み。", "terms": [["限定提供データ", "特定の相手に提供するため一定管理のもとで蓄積したデータを、不正な取得・使用から守る枠組み"], ["営業秘密", "秘密管理・有用・非公知の3要件で守る枠組み。限定提供データより秘密性が高い"]], "think": "「特定の相手に提供・管理されたデータの保護」なら限定提供データ。完全に秘密にして守る営業秘密とは、公開の程度が違う。", "vs": "営業秘密は秘密のまま守る枠組み(秘密性が高い)、特許権は発明を守る権利、著作権は表現を守る権利で、いずれも共有前提のデータを守る限定提供データではない。", "usecase": "有料で提供するデータセットや、業界で共有するデータを、営業秘密にはできないが保護したいときの枠組み。データ流通を後押しする。", "opt": ["正解。特定の相手に提供する管理されたデータを守るのが限定提供データ。", "秘密のまま守る枠組みで、共有前提の限定提供データとは秘密性が違う。", "発明を守る権利で、データを守る枠組みではない。", "表現を守る権利で、限定提供データではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q46', '公表された他人の著作物を、出所を明示し、自分の文章が主で引用が従となる形などの要件を満たして使う場合、許諾なく利用できる。この仕組みはどれか。', NULL, '["引用", "私的複製", "職務著作", "二次的著作物"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "出所明示・主従関係などの要件を満たせば許諾なく使える仕組みは？", "point": "「出所明示・自分が主で引用が従などの要件を満たせば許諾不要」なら、引用。", "kid": "他人の文章や図を、条件を守れば許可なく使える仕組みが引用。条件は「出所を書く」「自分の文が主で、引用は補助的(従)」「必要な範囲だけ」など。批評や研究で使える。", "eg": "レポートで他人の意見を「〜と述べている(出典)」と示しつつ、自分の主張の裏付けに少し借りる、あの使い方。", "terms": [["引用", "出所明示・主従関係などの要件を満たせば、公表された著作物を許諾なく使える仕組み"], ["著作権法30条の4", "機械学習の解析目的など、味わう目的でない利用を許諾なく認める別の規定"]], "think": "「出所明示・主従関係などの要件を満たして許諾なく使う」なら引用。要件を外れると単なる無断利用になる点に注意。", "vs": "私的複製は個人で楽しむための複製、職務著作は従業員が職務で作った著作物の権利の話、二次的著作物は原作を翻案して作った作品で、いずれも要件を満たして使う引用ではない。", "usecase": "論文・記事・プレゼンで他人の著作物を適法に使うための基本ルール。要件を守れば許諾交渉なしで使えるので実務で重要。", "opt": ["正解。出所明示や主従関係などの要件を満たせば許諾なく使えるのが引用。", "個人で楽しむための複製で、引用の要件の話ではない。", "従業員が職務で作った著作物の権利の話で、引用ではない。", "原作を翻案して作った作品のことで、引用の仕組みではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q47', '生成AIが、事実に反する内容を、あたかも正しいかのようにもっともらしく出力してしまう現象はどれか。', NULL, '["ハルシネーション", "ディープフェイク", "フィルターバブル", "敵対的サンプル"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "生成AIが事実に反する内容を、もっともらしく出力する現象は？", "point": "「生成AIが、事実でないことをもっともらしく答えてしまう」なら、ハルシネーション。", "kid": "生成AIは、それらしい言葉を続ける仕組みなので、事実を確認しているわけではない。だから、存在しない出典や間違った事実を、自信ありげに“それっぽく”出してしまうことがある。これがハルシネーション。", "eg": "よく知らないことを聞かれても、自信満々でそれらしく答えてしまう人、あの調子の良さ。", "terms": [["ハルシネーション", "生成AIが事実に反する内容を、もっともらしく出力してしまう現象"], ["RAG（検索拡張生成）", "外部の正しい情報を参照させて答えさせ、ハルシネーションを減らす工夫"]], "think": "「事実でないことをもっともらしく」ならハルシネーション。偽の映像を作るディープフェイクとは、起きる場面が違う(こちらは生成AIの出力の誤り)。", "vs": "ディープフェイクは本物そっくりの偽映像を作る技術、フィルターバブルは好みの情報に囲まれる現象、敵対的サンプルは入力を細工して誤らせる攻撃で、いずれも事実に反する出力のハルシネーションではない。", "usecase": "生成AIを業務で使う際の最大の注意点。事実確認や、外部情報を参照させる工夫(RAG)で被害を抑える、リスク管理の要。", "opt": ["正解。事実に反する内容をもっともらしく出すのがハルシネーション。", "本物そっくりの偽映像を作る技術で、生成AIの出力の誤りではない。", "好みの情報に囲まれる現象で、事実誤りの出力ではない。", "入力を細工して誤らせる攻撃で、ハルシネーションではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q48', '「1人を犠牲にすれば5人を救えるとき、どちらを選ぶべきか」のように、自動運転などで避けられない選択を迫られる倫理的ジレンマを指す語はどれか。', NULL, '["トロッコ問題", "フレーム問題", "中国語の部屋", "囚人のジレンマ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "「1人か5人か」のような、避けられない選択を迫る倫理的ジレンマは？", "point": "「誰かを犠牲にする選択を迫られる倫理的ジレンマ」なら、トロッコ問題。", "kid": "「このままだと5人が犠牲になるが、進路を変えれば別の1人が犠牲になる。どちらを選ぶ?」という、どちらも正解と言い切れない究極の選択。自動運転の事故回避の判断などで議論される。", "eg": "暴走するトロッコの進路を、5人のいる線路か1人のいる線路か、レバーで選ばされる、あの究極の二択。", "terms": [["トロッコ問題", "誰かを犠牲にする選択を迫られる倫理的ジレンマ。自動運転の判断などで論じられる"], ["AI倫理", "AIの判断が人の生命や権利に関わるときの、善悪や責任の考え方"]], "think": "「どちらも避けられない中での犠牲の選択」ならトロッコ問題。考える範囲を絞れないフレーム問題(技術的難問)とは種類が違う。", "vs": "フレーム問題は考える範囲を絞れない難問、中国語の部屋は理解と処理の分離を示す思考実験、囚人のジレンマは協力か裏切りかのゲーム理論の問題で、いずれも犠牲の選択を迫るトロッコ問題ではない。", "usecase": "自動運転車が事故を避けられないとき「誰を守るよう設計するか」という、答えの出しにくい倫理・責任の議論で引き合いに出される。", "opt": ["正解。誰かを犠牲にする選択を迫られる倫理的ジレンマがトロッコ問題。", "考える範囲を絞れない技術的な難問で、倫理の選択ではない。", "理解と処理の分離を示す思考実験で、犠牲の選択ではない。", "協力か裏切りかのゲーム理論の問題で、トロッコ問題ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q49', '日本で、AIに関わる主体を「開発者・提供者・利用者」に分け、それぞれが取り組むべき事項を示した指針はどれか。', NULL, '["AI事業者ガイドライン", "人間中心のAI社会原則", "著作権法30条の4", "ムーアの法則"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIの主体を開発者・提供者・利用者に分け、取り組むべき事項を示した指針は？", "point": "「開発者・提供者・利用者の3者に分けて、取り組む事項を示した指針」なら、AI事業者ガイドライン。", "kid": "AIに関わる人を「作る人(開発者)」「提供する人(提供者)」「使う人(利用者)」の3つに分け、それぞれが何に気をつけて取り組むべきかをまとめた、実務向けの指針。", "eg": "立場ごとに役割分担を書いた“業務マニュアル”のようなもの。作る側・売る側・使う側で気をつける点が違う。", "terms": [["AI事業者ガイドライン", "AIの開発者・提供者・利用者の3者に分け、取り組むべき事項を示した日本の指針"], ["人間中心のAI社会原則", "AIと社会の基本的な理念を示した、より上位の原則"]], "think": "「開発者・提供者・利用者の3分類で実務指針」ならAI事業者ガイドライン。理念を示す人間中心のAI社会原則より、具体的で実務寄り。", "vs": "人間中心のAI社会原則は基本理念を示す上位の原則、著作権法30条の4は機械学習の著作物利用の規定、ムーアの法則は半導体の性能向上の経験則で、いずれも3者に分けた実務指針ではない。", "usecase": "企業がAIを開発・提供・利用する際、自分の立場で何をすべきかを確認する拠り所。AIガバナンス整備の実務の土台。", "opt": ["正解。開発者・提供者・利用者の3者に分け取り組む事項を示すのがAI事業者ガイドライン。", "AIと社会の基本理念を示す上位の原則で、3者向けの実務指針ではない。", "機械学習の著作物利用の規定で、事業者向けの行動指針ではない。", "半導体の性能向上の経験則で、AIの指針ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-c-q50', '近年、AIの倫理・社会的課題として、大規模なモデルの学習が引き起こす問題が指摘されている。その一つはどれか。', NULL, '["大量の電力を消費し、環境に負荷をかける", "学習に必要なデータが年々減っていく", "モデルのサイズが自動で小さくなっていく", "計算コストが年々かからなくなっていく"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "大規模モデルの学習が引き起こす、倫理・社会的な問題の一つは？", "point": "「大規模モデルの学習が大量の電力を消費し、環境に負荷をかける」問題。", "kid": "巨大なモデルを学習させるには、膨大な計算＝大量の電力が要る。その分、二酸化炭素の排出など環境への負荷が大きくなる。これがAIの倫理・社会課題の一つ(環境保護)。", "eg": "超高性能なマシンを何日もフル稼働させ続ける“電気の大食い”。その電気を作る分だけ環境に負担がかかる。", "terms": [["AIの環境負荷", "大規模モデルの学習が大量の電力を消費し、二酸化炭素排出など環境に負担をかける問題"], ["省エネ・軽量化", "小さく効率的なモデルにして、環境負荷や計算コストを抑える取り組み"]], "think": "「大規模学習＝大量の電力＝環境負荷」が要点。モデルは大きくするほど計算も電力も増えるので、データやコストが減るという選択肢は逆。", "vs": "「データが減る」「サイズが自動で小さくなる」「コストがかからなくなる」は、いずれもモデルの大規模化の実態と逆で、環境負荷という指摘に当たらない。", "usecase": "AI開発で「性能を上げるほど電力も増える」トレードオフを意識する根拠。省エネや軽量化、再生可能エネルギー利用が課題になる。", "opt": ["正解。大量の電力を消費し、環境に負荷をかける点が問題。", "大規模化でデータはむしろ多く要るので、減るというのは逆。", "大規模化でサイズは大きくなる傾向で、自動で小さくはならない。", "大規模化で計算コストは増える傾向で、かからなくなるは逆。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-c' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
COMMIT;
